import React, { useState } from "react";
import { MdEmail } from "react-icons/md";
import { FaSquarePhone } from "react-icons/fa6";
import { SiInstagram } from "react-icons/si";
import { ImFacebook2, ImLinkedin } from "react-icons/im";
import { HiOutlineChevronRight } from "react-icons/hi";
import data from "../data/data.json";
import images from "../images";


const userData = data;

const Sidebar: React.FC = () => {
  const [open, setOpen] = useState(false);

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <>
      <div className={`sidebar text-white ${open ? "open" : ""}`}>
        <h2 className="text-xl font-bold mb-5">{userData.name}</h2>
        <a className={styles.row} href={`tel:${userData.phone}`}>
          <FaSquarePhone /> {formatPhoneNumber(userData.phone)}
        </a>
        <p>{userData.address}</p>
        <p>
          {userData.city}, {userData.province}, {userData.postalCode}
        </p>
        <a className={`${styles.row} mb-5`} href={`mailto:${userData.email}`}>
          <MdEmail /> {userData.email}
        </a>
        <div className="text-white social">
          <a href={userData.instagram} target="_blank" rel="noreferrer">
            <SiInstagram />
          </a>
          <a href={userData.facebook} target="_blank" rel="noreferrer">
            <ImFacebook2 />
          </a>
          <a href={userData.linkedin} target="_blank" rel="noreferrer">
            <ImLinkedin />
          </a>
        </div>

        <div className="flex flex-col absolute bottom-0 w-full">
            <img
              className="bg-white/70 p-4 mx-auto shadow-2xl w-44 mb-4"
              src={images.logo.src}
              alt={images.logo.src}
            />
          </div>

      </div>

      <button
        className="sidebar-toggle"
        onClick={() => setOpen((prev) => !prev)}
        aria-label="Toggle Sidebar"
      >
        <HiOutlineChevronRight className={`chevron-icon ${open ? "rotated" : ""}`} />
        <span className="text-white text-xs" >Contact</span>
      </button>
    </>
  );
};

export default Sidebar;

const styles = {
  row: "flex flex-row gap-2 items-center",
}