import React, { useState, useEffect, useRef } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { Dialog } from "@headlessui/react";
import { LiaWindowCloseSolid } from "react-icons/lia";
import { PiCaretLeftBold, PiCaretRightBold } from "react-icons/pi";


const categories = [
  "residential",
  "commercial",
  "bathroom",
  "restaurant",
  "clinic",
];

const GalleryThumbnailsModal: React.FC = () => {
  const { t } = useTranslation();
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const isTouchDevice = useRef(false);

  useEffect(() => {
    isTouchDevice.current =
      "ontouchstart" in window || navigator.maxTouchPoints > 0;
  }, []);

  const openModal = (category: string) => {
    setSelectedCategory(category);
    setCurrentIndex(0);
    setIsOpen(true);
  };

  const closeModal = () => {
    setIsOpen(false);
    setSelectedCategory(null);
    setCurrentIndex(0);
    setIsPaused(false);
  };

  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (isOpen && selectedCategory && !isPaused && !isTouchDevice.current) {
      const items = t(`${selectedCategory}.items`, {
        returnObjects: true,
      }) as any[];
      interval = setInterval(() => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % items.length);
      }, 4000);
    }

    return () => clearInterval(interval);
  }, [isOpen, selectedCategory, isPaused, t]);

  const handlePrev = () => {
    if (!selectedCategory) return;
    const items = t(`${selectedCategory}.items`, {
      returnObjects: true,
    }) as any[];
    setCurrentIndex((prevIndex) =>
      prevIndex === 0 ? items.length - 1 : prevIndex - 1
    );
  };

  const handleNext = () => {
    if (!selectedCategory) return;
    const items = t(`${selectedCategory}.items`, {
      returnObjects: true,
    }) as any[];
    setCurrentIndex((prevIndex) => (prevIndex + 1) % items.length);
  };

  return (
    <section className="w-full max-w-6xl mx-auto p-8">
      <h2 className="text-3xl text-accent mb-6">{t("gallery.title")}</h2>
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-6">
        {categories.map((category) => {
          const title = t(`${category}.title`);
          const thumbnailKey = t(`${category}.thumbnail`);
          const imgData = images[thumbnailKey];

          return (
            <div
              key={category}
              className="cursor-pointer text-center"
              onClick={() => openModal(category)}
            >
              <img
                src={imgData?.src}
                alt={imgData?.alt || title}
                className="rounded shadow hover:scale-105 transition"
              />
              <p className="mt-2 text-sm font-semibold text-gray-800">
                {title}
              </p>
            </div>
          );
        })}
      </div>

      <Dialog open={isOpen} onClose={closeModal} className="relative z-[100]">
        <div
          className="fixed inset-0 bg-black bg-opacity-70"
          aria-hidden="true"
        />
        <div className="fixed inset-0 flex items-center justify-center">
          <div
            className="bg-white rounded max-w-3xl w-full relative top-8 bottom-8"
            onMouseEnter={() => setIsPaused(true)}
            onMouseLeave={() => setIsPaused(false)}
          >
            <button
              onClick={closeModal}
              className="absolute -top-12 sm:-top-6 right-0 sm:-right-6 text-accent text-xl font-bold"
            >
              <LiaWindowCloseSolid className="text-5xl text-gray-200"/>
            </button>

            {selectedCategory &&
              (() => {
                const items = t(`${selectedCategory}.items`, {
                  returnObjects: true,
                }) as {
                  image: string;
                  item: string;
                }[];

                const currentItem = items[currentIndex];
                const imgData = images[currentItem?.image];

                return (
                  <>
                    <div className="relative flex items-center justify-center">
                      {/* Botón Anterior */}
                      <button
                        onClick={handlePrev}
                        className="absolute left-0 top-1/2 transform -translate-y-1/2  hover:bg-accent text-gray-700 px-2 py-1 rounded-l"
                        aria-label="Previous"
                      >
                        <PiCaretLeftBold className="text-6xl text-gray-200 text-shadow" />
                      </button>

                      {/* Imagen actual */}
                      <img
                        src={imgData?.src}
                        alt={currentItem?.item || "Gallery Image"}
                        className="w-full h-auto rounded"
                      />

                      {/* Botón Siguiente */}
                      <button
                        onClick={handleNext}
                        className="absolute right-0 top-1/2 transform -translate-y-1/2  hover:bg-accent text-gray-700 px-2 py-1 rounded-r"
                        aria-label="Next"
                      >
                        <PiCaretRightBold className="text-6xl text-gray-200 text-shadow" />
                      </button>
                    </div>


                    {/* Descripción debajo de la imagen */}
                    <div className="absolute top-8 justify-center text-white text-shadow text-center">
                        <p className="text-xl font-semibold">{currentItem?.item}</p>
                    </div>

                    {/* Indicadores */}
                    <div className="absolute bottom-8 justify-center flex space-x-2 mx-auto w-full">
                      {items.map((_, index) => (
                        <button
                          key={index}
                          onClick={() => setCurrentIndex(index)}
                          className={`w-3 h-3 rounded-full ${
                            index === currentIndex ? "bg-accent" : "bg-gray-300"
                          } transition`}
                          aria-label={`Go to slide ${index + 1}`}
                        />
                      ))}
                    </div>
                  </>
                );
              })()}
          </div>
        </div>
      </Dialog>
    </section>
  );
};

export default GalleryThumbnailsModal;
